/* Deutsch mit Liedern – eigene Lieder (Text: Dzianis Prudnikau, Musik: Suno). suno = Song-ID bei Suno. */
(window.DM || (window.DM = {})).songs = [{"id": "a1-01-hallo", "level": "A1", "title": "Hallo, ich bin neu hier", "theme": "Sich vorstellen: Name, Herkunft, Wohnort, Beruf, Sprachen", "grammar": "Präsens (sein, heißen, kommen, wohnen, sprechen), W-Fragen (Wie? Woher? Wo?)", "intro": "Dein erstes Lied auf Deutsch: Hier stellen sich zwei neue Kursteilnehmer vor. Sing mit und stell dich danach selbst vor!", "lyrics": "[Verse 1]\nHallo, hallo! Ich bin neu hier.\nIch heiße Mira – und wer bist du? Sag es mir!\nIch komme aus Syrien, ich wohne in Essen.\nIch lerne Deutsch am Morgen und nach dem Essen.\n\n[Chorus]\nWie heißt du? Woher kommst du?\nWo wohnst du? Ich höre zu.\nWie heißt du? Woher kommst du?\nHallo, hallo – ich und du!\n\n[Verse 2]\nHallo, ich heiße Tarek, ich komme aus Marokko.\nIch wohne in Bochum und ich trinke gern Kakao.\nIch bin Koch von Beruf und ich koche gern.\nIch spreche Arabisch – und Deutsch lerne ich gern.\n\n[Chorus]\nWie heißt du? Woher kommst du?\nWo wohnst du? Ich höre zu.\nWie heißt du? Woher kommst du?\nHallo, hallo – ich und du!\n\n[Bridge]\nFreut mich! – Freut mich auch!\nFreut mich! – Freut mich auch!\nHerzlich willkommen hier im Kurs!\n\n[Outro]\nWie heißt du? Woher kommst du?\nHallo, hallo – ich und du!", "vocab": [["der Name, die Namen", "So heißt eine Person, z. B. Mira oder Tarek."], ["heißen", "„Mein Name ist …“ – das sagt man auch so: „Ich … Mira.“"], ["kommen aus", "sagen, aus welchem Land man ist"], ["wohnen in", "Hier ist meine Wohnung, z. B. in Essen."], ["der Kurs, die Kurse", "Hier lernen viele Menschen zusammen."], ["der Beruf, die Berufe", "die Arbeit, z. B. Lehrerin, Ärztin oder Koch"], ["der Koch, die Köche", "Er macht das Essen im Restaurant."], ["sprechen", "Wörter sagen, z. B. Arabisch oder Deutsch"], ["lernen", "Neues im Kopf speichern, z. B. im Kurs"], ["Freut mich!", "Das sagt man: Schön, dich kennenzulernen."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich komme aus Syrien, ich ___ in Essen.", "Wo wohnst du? Ich ___ zu.", "Ich bin Koch von ___ und ich koche gern.", "Ich ___ Arabisch – und Deutsch lerne ich gern.", "Herzlich willkommen hier im ___!"], "solutions": ["wohne", "höre", "Beruf", "spreche", "Kurs"]}, "suno": "4b7dd70f-7896-4953-a910-821437e1f6d7"}, {"id": "a1-02-wie-spaet", "level": "A1", "title": "Wie spät ist es?", "theme": "Zahlen und Uhrzeit, Tagesablauf", "grammar": "Uhrzeit (Wie spät ist es? Um wie viel Uhr?), Zahlen, Präsens, trennbares Verb aufstehen", "intro": "Eins, zwei, drei – und los! In diesem Reggae-Song lernst du Zahlen und die Uhrzeit. Achte auf „halb“ und „Viertel“!", "lyrics": "[Verse 1]\nEins, zwei, drei – der Tag ist neu.\nVier, fünf, sechs – ich stehe auf um sechs.\nSieben, acht – der Kaffee ist gemacht.\nNeun und zehn – ich muss jetzt gehen.\n\n[Chorus]\nWie spät ist es? Wie spät ist es?\nEs ist acht Uhr – nicht vergessen!\nWie spät ist es? Sag es mir!\nEs ist acht Uhr – der Bus ist hier!\n\n[Verse 2]\nUm halb neun beginnt der Kurs,\num Viertel nach zehn ist Pause – ich habe Durst!\nUm Viertel vor eins ist der Unterricht aus,\ndann fahre ich mit dem Bus nach Haus.\n\n[Chorus]\nWie spät ist es? Wie spät ist es?\nEs ist acht Uhr – nicht vergessen!\nWie spät ist es? Sag es mir!\nEs ist acht Uhr – der Bus ist hier!\n\n[Bridge]\nZehn, zwanzig, dreißig, vierzig, fünfzig –\nsechzig Minuten hat die Stunde. Richtig!\nVierundzwanzig Stunden hat ein Tag.\n\n[Outro]\nWie spät ist es? Es ist zehn nach drei.\nDer Tag ist um – und ich bin frei!", "vocab": [["die Uhr, die Uhren", "Sie zeigt die Zeit."], ["halb neun", "8:30 Uhr"], ["Viertel nach zehn", "10:15 Uhr"], ["Viertel vor eins", "12:45 Uhr"], ["die Pause, die Pausen", "kurze Zeit ohne Arbeit oder Unterricht"], ["beginnen", "anfangen, starten"], ["aufstehen", "morgens aus dem Bett kommen"], ["die Stunde, die Stunden", "60 Minuten"], ["die Minute, die Minuten", "60 Sekunden"], ["der Durst", "Ich möchte etwas trinken."], ["der Unterricht", "die Zeit im Kurs mit der Lehrerin oder dem Lehrer"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Vier, fünf, sechs – ich ___ auf um sechs.", "Um ___ neun beginnt der Kurs,", "um Viertel nach zehn ist ___ – ich habe Durst!", "dann fahre ich mit dem ___ nach Haus.", "Vierundzwanzig ___ hat ein Tag."], "solutions": ["stehe", "halb", "Pause", "Bus", "Stunden"]}, "suno": "65539704-d378-4075-8c7e-001e087b2eb2"}, {"id": "a1-03-familie", "level": "A1", "title": "Das ist meine Familie", "theme": "Familie und Verwandte", "grammar": "Possessivartikel mein/meine/dein/deine, haben + Akkusativ (einen/eine/ein, kein/keine)", "intro": "Wer gehört zu deiner Familie? In diesem Folk-Song stellt eine Frau ihre Familie vor. Danach kannst du deine eigene Familie beschreiben.", "lyrics": "[Verse 1]\nDas ist mein Vater, er kocht sehr gut.\nDas ist meine Mutter, sie hat viel Mut.\nIch habe einen Bruder und eine Schwester,\nmein Bruder heißt Sami, und sie heißt Esther.\n\n[Chorus]\nDas ist meine Familie,\nich liebe sie, ich liebe sie!\nUnd du, und du – wie groß ist deine Familie?\nKomm, erzähl es mir!\n\n[Verse 2]\nMeine Oma ist alt, sie ist achtzig Jahre.\nMein Opa ist lustig, er hat keine Haare.\nMeine Schwester hat ein Baby, so süß und klein.\nIch bin jetzt Tante – das ist so fein!\n\n[Chorus]\nDas ist meine Familie,\nich liebe sie, ich liebe sie!\nUnd du, und du – wie groß ist deine Familie?\nKomm, erzähl es mir!\n\n[Bridge]\nHast du einen Bruder? – Ja, ich habe einen Bruder.\nHast du eine Schwester? – Nein, ich habe keine Schwester.\nHast du ein Kind? – Ja, ich habe ein Kind.\nWir sind eine Familie – so, wie wir sind.\n\n[Outro]\nDas ist meine Familie!", "vocab": [["der Vater, die Väter", "der Papa"], ["die Mutter, die Mütter", "die Mama"], ["der Bruder, die Brüder", "ein Junge oder Mann mit denselben Eltern wie ich"], ["die Schwester, die Schwestern", "ein Mädchen oder eine Frau mit denselben Eltern wie ich"], ["die Oma, die Omas", "die Mutter von Mama oder Papa"], ["der Opa, die Opas", "der Vater von Mama oder Papa"], ["das Baby, die Babys", "ein sehr kleines Kind"], ["die Tante, die Tanten", "die Schwester von Mama oder Papa"], ["die Familie, die Familien", "Eltern, Kinder, Oma, Opa …"], ["der Mut", "keine Angst haben"], ["lustig", "Die Person macht Witze, man lacht viel."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Das ist mein ___, er kocht sehr gut.", "Ich habe ___ Bruder und eine Schwester,", "Meine Oma ist alt, sie ist ___ Jahre.", "Meine Schwester hat ein ___, so süß und klein.", "Hast du eine Schwester? – Nein, ich habe ___ Schwester."], "solutions": ["Vater", "einen", "achtzig", "Baby", "keine"]}, "suno": "39346fc5-7cbb-448c-80e8-d6ba300fbf91"}, {"id": "a1-04-supermarkt", "level": "A1", "title": "Im Supermarkt", "theme": "Essen und Einkaufen, Preise, Bezahlen", "grammar": "Akkusativ (einen/eine/ein), möchten, Fragen nach dem Preis (Was kostet …?)", "intro": "Dein Kühlschrank ist leer? Dann ab in den Supermarkt! Mit diesem Funk-Song übst du Lebensmittel, Preise und Bezahlen.", "lyrics": "[Verse 1]\nIch gehe heute in den Supermarkt,\nich brauche Brot, ich brauche Quark.\nEin Kilo Äpfel und einen Salat,\nund Milch und Eier – dann bin ich satt.\n\n[Chorus]\nWas möchten Sie? – Ich möchte Brot.\nWas kostet das? – Zwei Euro. Gut!\nWas möchten Sie? – Ich nehme Tee.\nDanke schön! – Bitte schön! Tschüss und ade!\n\n[Verse 2]\nIch suche Reis – wo ist der Reis?\nDie Verkäuferin sagt: „Ich weiß, ich weiß!\nDa hinten links, im Regal Nummer drei.“\nIch kaufe noch Tomaten – und dann bin ich frei.\n\n[Chorus]\nWas möchten Sie? – Ich möchte Brot.\nWas kostet das? – Zwei Euro. Gut!\nWas möchten Sie? – Ich nehme Tee.\nDanke schön! – Bitte schön! Tschüss und ade!\n\n[Bridge]\nZahlen Sie bar oder mit Karte?\nMit Karte, bitte – ich warte.\nBrauchen Sie eine Tüte? – Nein, danke schön,\nich habe eine Tasche. Auf Wiedersehen!\n\n[Outro]\nWas möchten Sie? – Ich möchte Brot.\nDanke schön! – Bitte schön!", "vocab": [["der Supermarkt, die Supermärkte", "ein großes Geschäft für Essen und Getränke"], ["das Brot, die Brote", "Man isst es zum Frühstück, mit Butter und Käse."], ["das Kilo, die Kilos", "1000 Gramm"], ["der Apfel, die Äpfel", "rundes Obst, rot oder grün"], ["der Reis", "kleine weiße Körner, man kocht sie in Wasser"], ["das Regal, die Regale", "Hier stehen die Produkte im Geschäft."], ["bar zahlen", "mit Münzen und Scheinen bezahlen"], ["die Tüte, die Tüten", "aus Plastik oder Papier, für den Einkauf"], ["die Verkäuferin, die Verkäuferinnen", "Sie arbeitet im Geschäft und hilft."], ["die Karte, die Karten", "Bankkarte: Man bezahlt ohne Münzen und Scheine."], ["satt", "Ich habe keinen Hunger mehr."], ["das Ei, die Eier", "Das Huhn legt es."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich ___ Brot, ich brauche Quark.", "Ein ___ Äpfel und einen Salat,", "Was ___ das? – Zwei Euro. Gut!", "Da hinten links, im ___ Nummer drei.“", "Zahlen Sie ___ oder mit Karte?"], "solutions": ["brauche", "Kilo", "kostet", "Regal", "bar"]}, "suno": "2f5f7692-f67a-4a0a-bef1-219e4e5191ef"}, {"id": "a1-05-meine-woche", "level": "A1", "title": "Meine Woche", "theme": "Wochentage und Tagesablauf", "grammar": "Trennbare Verben (aufstehen, aufräumen, anrufen, einkaufen, fernsehen, mitkommen, ausschlafen), am + Wochentag", "intro": "Montag, Dienstag, Mittwoch … Was machst du jeden Tag? In diesem Indie-Pop-Song lernst du die Wochentage und trennbare Verben.", "lyrics": "[Verse 1]\nAm Montag stehe ich früh auf,\nam Dienstag räume ich die Küche auf.\nAm Mittwoch rufe ich Mama an,\nam Donnerstag kaufe ich ein – und dann?\n\n[Chorus]\nMontag, Dienstag, Mittwoch, Donnerstag,\nFreitag, Samstag, Sonntag – jeden Tag!\nWas machst du am Montag? Was machst du heute?\nDie Woche ist lang – hallo, liebe Leute!\n\n[Verse 2]\nAm Freitag sehe ich am Abend fern,\nich esse Pizza – Pizza esse ich gern.\nAm Samstag gehe ich tanzen, mein Freund kommt mit,\nwir tanzen zusammen, Schritt für Schritt.\n\n[Chorus]\nMontag, Dienstag, Mittwoch, Donnerstag,\nFreitag, Samstag, Sonntag – jeden Tag!\nWas machst du am Montag? Was machst du heute?\nDie Woche ist lang – hallo, liebe Leute!\n\n[Bridge]\nUnd am Sonntag? Am Sonntag?\nAm Sonntag schlafe ich lange aus,\nich bleibe gern zu Haus.\nIch bleibe gern zu Haus!\n\n[Outro]\nMontag, Dienstag, Mittwoch … und du?\nWas machst du am Sonntag? Und du?", "vocab": [["aufstehen", "morgens aus dem Bett kommen"], ["aufräumen", "Ordnung machen, alles an seinen Platz legen"], ["anrufen", "mit dem Handy oder Telefon eine Person kontaktieren"], ["einkaufen", "in den Supermarkt gehen und Essen holen"], ["fernsehen", "einen Film oder Nachrichten im TV anschauen"], ["mitkommen", "zusammen mit einer Person gehen"], ["ausschlafen", "morgens sehr lange im Bett bleiben, ohne Wecker"], ["die Woche, die Wochen", "sieben Tage"], ["der Abend, die Abende", "die Zeit nach der Arbeit, ungefähr 18 bis 22 Uhr"], ["zu Hause", "in meiner Wohnung"], ["tanzen", "sich zur Musik bewegen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Am Montag stehe ich ___ auf,", "Am Mittwoch ___ ich Mama an,", "Am Freitag sehe ich am Abend ___,", "ich esse Pizza – Pizza esse ich ___.", "Am Sonntag schlafe ich lange ___,"], "solutions": ["früh", "rufe", "fern", "gern", "aus"]}, "suno": "1c673ea8-5bca-4174-94e2-79b77a8987c1"}, {"id": "a2-01-neue-wohnung", "level": "A2", "title": "Meine neue Wohnung", "theme": "Wohnung, Umzug, Möbel, Nachbarn", "grammar": "Wechselpräpositionen: Wohin? + Akkusativ (stellen, legen, hängen) / Wo? + Dativ (stehen, liegen, hängen); Perfekt", "intro": "Endlich eine eigene Wohnung! Aber wohin mit dem Sofa? In diesem Schlager-Pop-Song übst du Wo? und Wohin? mit Möbeln.", "lyrics": "[Verse 1]\nIch bin umgezogen, das war viel Arbeit,\njetzt wohne ich in Gelsenkirchen – endlich ist es so weit!\nZwei Zimmer, Küche, Bad und ein kleiner Balkon,\ndie Kisten sind noch da, aber ich wohne hier schon.\n\n[Chorus]\nWohin? Wohin? – Ich stelle das Sofa an die Wand.\nWo? Wo? – Das Sofa steht an der Wand.\nWohin? Wohin? – Ich hänge das Bild über das Bett.\nWo? Wo? – Es hängt über dem Bett. Wie nett!\n\n[Verse 2]\nIch habe den Tisch in die Küche gestellt,\ndie Lampe hängt im Flur – sie war billig, für wenig Geld.\nDen Teppich habe ich ins Wohnzimmer gelegt,\ndie Pflanze steht am Fenster, ich habe sie gut gepflegt.\n\n[Chorus]\nWohin? Wohin? – Ich stelle das Sofa an die Wand.\nWo? Wo? – Das Sofa steht an der Wand.\nWohin? Wohin? – Ich hänge das Bild über das Bett.\nWo? Wo? – Es hängt über dem Bett. Wie nett!\n\n[Bridge]\nDie Nachbarin hat geklingelt und Kuchen mitgebracht,\nwir haben Kaffee getrunken und zusammen gelacht.\nJetzt liege ich auf dem Sofa – mein neues Zuhause, gute Nacht!\n\n[Outro]\nWo wohne ich? Hier wohne ich.\nWillkommen bei mir!", "vocab": [["umziehen (ist umgezogen)", "in eine neue Wohnung gehen und dort wohnen"], ["die Miete, die Mieten", "Geld für die Wohnung, jeden Monat"], ["der Balkon, die Balkone", "kleiner Platz draußen an der Wohnung"], ["die Kiste, die Kisten", "großer Karton für Sachen beim Umzug"], ["stellen (wohin?)", "etwas aufrecht an einen Ort bringen, z. B. einen Tisch"], ["legen (wohin?)", "etwas flach an einen Ort bringen, z. B. ein Buch"], ["der Flur, die Flure", "Raum hinter der Wohnungstür, von dort geht man in die Zimmer"], ["der Teppich, die Teppiche", "Er liegt auf dem Boden, weich und warm."], ["die Nachbarin, die Nachbarinnen", "Frau, die neben mir wohnt"], ["das Zuhause", "der Ort, wo ich wohne und mich wohlfühle"], ["klingeln", "an der Tür auf den Knopf drücken"], ["pflegen", "gut für etwas sorgen, z. B. Wasser für Blumen geben"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["die ___ sind noch da, aber ich wohne hier schon.", "Ich habe den Tisch in die Küche ___,", "Den ___ habe ich ins Wohnzimmer gelegt,", "Die Nachbarin hat ___ und Kuchen mitgebracht,", "wir haben Kaffee ___ und zusammen gelacht."], "solutions": ["Kisten", "gestellt", "Teppich", "geklingelt", "getrunken"]}, "suno": "ea390cc6-e053-464f-9a95-f1cd0ded87e5"}, {"id": "a2-02-beim-arzt", "level": "A2", "title": "Gute Besserung", "theme": "Beim Arzt: Krankheiten, Körper, Medikamente, Krankmeldung", "grammar": "Modalverben müssen, dürfen, sollen; weh tun; weil-Sätze", "intro": "Kopfschmerzen, Fieber, Husten – was jetzt? In dieser Akustik-Ballade gehst du zur Ärztin und lernst, was du musst, darfst und sollst.", "lyrics": "[Verse 1]\nMein Kopf tut weh, mein Hals tut weh,\nich habe Fieber – oje, oje!\nIch rufe in der Praxis an – ich muss heute hin,\nweil ich so krank und so müde bin.\n\n[Verse 2]\n„Was fehlt Ihnen denn?“, fragt die Ärztin mich.\n„Ich huste in der Nacht, ich schlafe schlecht – ich kann nicht mehr, ehrlich!“\n„Machen Sie bitte den Mund auf und sagen Sie ‚Aaah‘!\nSie haben eine Erkältung, das ist ganz klar.“\n\n[Chorus]\nSie müssen viel trinken, Sie dürfen nicht rauchen,\nSie sollen im Bett bleiben – Ruhe ist, was Sie jetzt brauchen.\nGute Besserung! Gute Besserung!\nBleiben Sie zu Hause und werden Sie schnell gesund!\n\n[Verse 3]\nIch bekomme ein Rezept und eine Krankmeldung,\nfür meinen Chef – und alles ist in Ordnung.\nIn der Apotheke hole ich Tabletten und Tee,\nich nehme sie dreimal am Tag – bald tut nichts mehr weh.\n\n[Bridge]\nDarf ich arbeiten? – Nein, das dürfen Sie nicht.\nMuss ich wiederkommen? – Ja, am Freitag, das ist Pflicht.\nDarf ich Sport machen? – Nein, noch nicht!\n\n[Outro]\nGute Besserung – und bis bald!", "vocab": [["wehtun (Der Kopf tut weh.)", "Schmerzen machen, z. B. im Kopf oder im Bauch"], ["das Fieber", "Die Körpertemperatur ist hoch, z. B. 39 Grad."], ["die Erkältung, die Erkältungen", "leichte Krankheit mit Schnupfen, Husten und Halsschmerzen"], ["die Praxis, die Praxen", "Hier arbeitet die Ärztin, dort wartet man auf den Termin."], ["das Rezept, die Rezepte", "Papier vom Arzt für Medikamente"], ["die Krankmeldung, die Krankmeldungen", "Papier vom Arzt für den Chef: Ich kann nicht arbeiten."], ["die Apotheke, die Apotheken", "Geschäft für Medikamente"], ["die Tablette, die Tabletten", "kleines Medikament zum Schlucken"], ["Gute Besserung!", "Das sagt man zu kranken Menschen: Werde schnell gesund!"], ["die Ruhe", "keine Arbeit, kein Stress, kein Lärm"], ["Was fehlt Ihnen?", "Frage beim Arzt: Welches Problem haben Sie?"], ["die Pflicht, die Pflichten", "Das muss man machen."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Mein Kopf tut weh, mein ___ tut weh,", "ich habe ___ – oje, oje!", "Sie müssen viel trinken, Sie ___ nicht rauchen,", "Ich bekomme ein ___ und eine Krankmeldung,", "ich nehme sie ___ am Tag – bald tut nichts mehr weh."], "solutions": ["Hals", "Fieber", "dürfen", "Rezept", "dreimal"]}, "suno": "d899bdd0-7cb7-422b-b2c7-bc1251011787"}, {"id": "a2-03-jahreszeiten", "level": "A2", "title": "Jede Jahreszeit", "theme": "Wetter und Jahreszeiten", "grammar": "Nebensätze mit weil und dass; im + Jahreszeit/Monat; Perfekt", "intro": "Sonne, Regen, Wind und Schnee: Dieser Folk-Song wandert durch das Jahr. Du übst Wetterwörter und Sätze mit „weil“ und „dass“.", "lyrics": "[Verse 1]\nIm Frühling ist es mild, die Sonne kommt zurück,\nich gehe gern spazieren, weil die Blumen blühen – so ein Glück!\nIm Sommer ist es heiß, das Thermometer zeigt dreißig Grad,\nich fahre an den See mit meinem Fahrrad.\n\n[Chorus]\nIch mag jede Jahreszeit, weil jede anders ist.\nIch weiß, dass du die Sonne im Winter oft vermisst.\nRegen, Wind und Schnee – egal, ich gehe raus,\nund abends trinke ich Tee zu Haus.\n\n[Verse 2]\nIm Herbst ist es windig, die Blätter werden bunt,\nes regnet oft – doch ich gehe raus, denn das ist gesund.\nIm Winter ist es kalt, manchmal schneit es im Dezember,\num fünf Uhr ist es dunkel – schon seit Anfang November.\n\n[Chorus]\nIch mag jede Jahreszeit, weil jede anders ist.\nIch weiß, dass du die Sonne im Winter oft vermisst.\nRegen, Wind und Schnee – egal, ich gehe raus,\nund abends trinke ich Tee zu Haus.\n\n[Bridge]\nUnd gestern? Gestern hat es den ganzen Tag geregnet.\nIch bin im Treppenhaus nur meinem Nachbarn begegnet.\nWir haben gelacht und gesagt: „Na und?\nMorgen scheint die Sonne wieder – bleib gesund!“", "vocab": [["die Jahreszeit, die Jahreszeiten", "Frühling, Sommer, Herbst oder Winter"], ["mild", "nicht zu kalt und nicht zu warm"], ["blühen", "Die Blumen öffnen sich und haben Farben."], ["das Thermometer, die Thermometer", "Es zeigt die Temperatur."], ["das Blatt, die Blätter", "Es ist grün am Baum und fällt im Herbst."], ["windig", "Die Luft bewegt sich stark."], ["schneien", "Weiße, kalte Flocken fallen vom Himmel."], ["vermissen", "traurig sein, weil etwas oder jemand nicht da ist"], ["begegnen (+ Dativ)", "eine Person zufällig treffen"], ["dunkel", "ohne Licht"], ["das Treppenhaus, die Treppenhäuser", "Dort sind die Treppen in einem Wohnhaus."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich gehe gern spazieren, weil die Blumen ___ – so ein Glück!", "ich fahre an den ___ mit meinem Fahrrad.", "Ich weiß, dass du die Sonne im Winter oft ___.", "Im Herbst ist es ___, die Blätter werden bunt,", "um fünf Uhr ist es ___ – schon seit Anfang November."], "solutions": ["blühen", "See", "vermisst", "windig", "dunkel"]}, "suno": "738c1f98-da42-49e1-acc8-0850e495b2a5"}, {"id": "a2-04-wir-feiern", "level": "A2", "title": "Heute feiern wir", "theme": "Feste und Feiern: Geburtstag, Weihnachten, Zuckerfest, Geschenke", "grammar": "Dativ: Verben mit zwei Objekten (schenken, geben, bringen) und Personalpronomen im Dativ (mir, dir, ihm, ihr, uns, ihnen); gratulieren + Dativ", "intro": "Geburtstag, Weihnachten, Zuckerfest – wir feiern zusammen! Mit diesem Funk-Song übst du, wem du was schenkst.", "lyrics": "[Verse 1]\nHeute ist ein Fest, wir feiern bis zur Nacht,\nich habe meiner Freundin einen Kuchen gemacht.\nIch schenke ihr Blumen und ich singe ihr ein Lied,\nund alle unsere Freunde singen laut mit.\n\n[Chorus]\nAlles Gute! Alles Gute!\nHerzlichen Glückwunsch – heute feiern wir!\nWir gratulieren dir, wir danken dir,\nwir sind so froh – du bist hier!\n\n[Verse 2]\nIm Dezember feiern viele Menschen Weihnachten,\nwir schenken unseren Eltern warme Socken – und alle lachen.\nMein Nachbar feiert mit seiner Familie das Zuckerfest,\ner bringt uns Süßigkeiten – so ein schönes Fest!\n\n[Chorus]\nAlles Gute! Alles Gute!\nHerzlichen Glückwunsch – heute feiern wir!\nWir gratulieren dir, wir danken dir,\nwir sind so froh – du bist hier!\n\n[Bridge]\nWas schenkst du deiner Mutter? – Ich schenke ihr Blumen.\nWas schenkst du deinem Bruder? – Ich schenke ihm ein Spiel.\nWas schenkst du deinen Kindern? – Ich schenke ihnen Zeit,\ndenn Zeit zusammen ist das Schönste – weit und breit.\n\n[Chorus]\nAlles Gute! Alles Gute!\nHerzlichen Glückwunsch – heute feiern wir!\nWir gratulieren dir, wir danken dir,\nwir sind so froh – du bist hier!\n\n[Outro]\nHerzlichen Glückwunsch – wir feiern mit dir!", "vocab": [["feiern", "eine Party machen, einen besonderen Tag zusammen erleben"], ["das Fest, die Feste", "großer Tag mit Essen, Musik und Gästen"], ["schenken (jemandem etwas)", "jemandem etwas geben, ohne Geld dafür zu nehmen"], ["gratulieren (+ Dativ)", "Glück wünschen, z. B. zum Geburtstag"], ["Herzlichen Glückwunsch!", "Das sagt man am Geburtstag oder zur Hochzeit."], ["Weihnachten", "christliches Fest vom 24. bis 26. Dezember"], ["das Zuckerfest", "Fest am Ende vom Ramadan"], ["die Süßigkeit, die Süßigkeiten", "Schokolade, Bonbons, Kekse"], ["die Socke, die Socken", "Man trägt sie an den Füßen, im Schuh."], ["das Geschenk, die Geschenke", "Man bekommt es zum Geburtstag, oft in buntem Papier."], ["weit und breit", "überall, im ganzen Umkreis"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich habe meiner Freundin einen ___ gemacht.", "Ich schenke ihr ___ und ich singe ihr ein Lied,", "Herzlichen Glückwunsch – heute ___ wir!", "Wir ___ dir, wir danken dir,", "er bringt uns ___ – so ein schönes Fest!"], "solutions": ["Kuchen", "Blumen", "feiern", "gratulieren", "Süßigkeiten"]}, "suno": "07b5f491-6d96-44b2-b963-7ba44454bfab"}, {"id": "a2-05-gleis-sieben", "level": "A2", "title": "Gleis sieben", "theme": "Reise und Bahnhof: Tickets, Verspätung, Umsteigen, Ankommen", "grammar": "Perfekt mit haben und sein (Bewegungsverben), Präpositionen mit, nach, zu, in, um", "intro": "Mit dem Zug nach Hamburg – und natürlich gibt es Verspätung! In diesem entspannten Hip-Hop-Song erzählst du im Perfekt von einer Reise.", "lyrics": "[Verse 1]\nIch bin heute früh zum Bahnhof gegangen,\ndie Reise nach Hamburg hat um acht angefangen.\nIch habe mein Ticket online gebucht,\ndann habe ich lange das Gleis gesucht.\n\n[Chorus]\nGleis sieben, Gleis sieben – wo ist mein Zug?\nZehn Minuten Verspätung – ich habe Zeit genug.\nIch warte, ich warte, ich trinke Kaffee,\ndann kommt der ICE – ich steige ein, juchhe!\n\n[Verse 2]\nIn Münster musste ich leider umsteigen,\nder Anschluss war weg – ich konnte nur schweigen.\nDie Zugbegleiterin hat gesagt: „Es tut mir leid,\nder nächste Zug fährt in einer Stunde – Sie haben noch Zeit.“\n\n[Chorus]\nGleis sieben, Gleis sieben – wo ist mein Zug?\nZehn Minuten Verspätung – ich habe Zeit genug.\nIch warte, ich warte, ich trinke Kaffee,\ndann kommt der ICE – ich steige ein, juchhe!\n\n[Verse 3]\nUm drei Uhr bin ich endlich in Hamburg angekommen,\nmeine Tante hat mich am Bahnhof in den Arm genommen.\nWir sind mit der U-Bahn zu ihr gefahren,\nwie früher, wie vor vielen Jahren.\n\n[Bridge]\nEinfach oder hin und zurück?\nZweite Klasse, Fensterplatz – mit ein bisschen Glück.\nGute Reise! Gute Fahrt!\n\n[Outro]\nGleis sieben, Gleis sieben –\nich bin da.", "vocab": [["der Bahnhof, die Bahnhöfe", "Hier fahren Züge ab und kommen an."], ["das Gleis, die Gleise", "Hier hält der Zug; es hat eine Nummer."], ["buchen", "ein Ticket oder ein Hotel reservieren und bezahlen"], ["die Verspätung, die Verspätungen", "Der Zug kommt später als geplant."], ["umsteigen (ist umgestiegen)", "einen Zug verlassen und in einen anderen gehen"], ["der Anschluss, die Anschlüsse", "der nächste Zug auf der Reise, den man erreichen muss"], ["die Zugbegleiterin, die Zugbegleiterinnen", "Sie arbeitet im Zug und kontrolliert die Tickets."], ["ankommen (ist angekommen)", "am Ziel sein"], ["einsteigen (ist eingestiegen)", "in den Zug oder Bus gehen"], ["hin und zurück", "die Fahrt zum Ziel und wieder nach Hause"], ["der Fensterplatz, die Fensterplätze", "Sitz direkt neben dem Fenster"], ["schweigen", "nichts sagen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich habe mein Ticket online ___,", "Zehn Minuten ___ – ich habe Zeit genug.", "In Münster musste ich leider ___,", "Um drei Uhr bin ich endlich in Hamburg ___,", "Wir sind mit der ___ zu ihr gefahren,"], "solutions": ["gebucht", "Verspätung", "umsteigen", "angekommen", "U-Bahn"]}, "suno": "87e14303-4687-40f3-a2a3-b175cbd80a08"}, {"id": "b1-01-ich-bewerbe-mich", "level": "B1", "title": "Ich bewerbe mich", "theme": "Arbeit und Bewerbung: Stellenanzeige, Unterlagen, Vorstellungsgespräch", "grammar": "Nebensätze mit weil, obwohl, wenn, dass und indirekte Fragen (warum …)", "intro": "Lebenslauf, Anschreiben, Vorstellungsgespräch – dieser motivierende Hip-Hop-Song begleitet dich auf dem Weg zum neuen Job. Du übst Nebensätze mit weil, obwohl, wenn und dass.", "lyrics": "[Verse 1]\nIch sitze am Laptop, es ist schon spät,\nich schreibe eine Bewerbung, weil es um meine Zukunft geht.\nLebenslauf, Anschreiben, Zeugnisse – alles in die Mappe,\nund obwohl ich nervös bin, sage ich mir: Ich schaffe das!\nIch habe in der Anzeige gelesen, dass sie Pflegekräfte suchen,\nin Teilzeit oder Vollzeit – nicht nur träumen, sondern versuchen!\n\n[Chorus]\nWenn ich die Chance bekomme, zeige ich, was ich kann.\nIch bin pünktlich und zuverlässig – sagen Sie mir: Wann fange ich an?\nIch bewerbe mich, ich bewerbe mich,\nmit Herz und mit Erfahrung – und ich bin ehrlich.\n\n[Verse 2]\nEine Woche später kommt eine Mail – ich lese sie zweimal:\nEinladung zum Vorstellungsgespräch – ich jubele: genial!\nIch bügle mein Hemd und übe jeden Satz,\nStärken, Schwächen, Ziele – alles hat seinen Platz.\n\n[Chorus]\nWenn ich die Chance bekomme, zeige ich, was ich kann.\nIch bin pünktlich und zuverlässig – sagen Sie mir: Wann fange ich an?\nIch bewerbe mich, ich bewerbe mich,\nmit Herz und mit Erfahrung – und ich bin ehrlich.\n\n[Verse 3]\nIm Gespräch fragt die Chefin, warum ich hier bin.\nIch sage: „Weil ich Menschen helfen will – das gibt meinem Leben Sinn.\nObwohl mein Deutsch nicht perfekt ist, lerne ich jeden Tag,\nund wenn ich etwas nicht verstehe, dann frage ich nach.“\n\n[Bridge]\nSie lächelt und sagt: „Wir melden uns bei Ihnen.“\nDrei Tage später: Zusage! Jetzt kann ich mein Geld verdienen.", "vocab": [["die Bewerbung, die Bewerbungen", "Unterlagen, mit denen man sich um eine Stelle bemüht"], ["der Lebenslauf, die Lebensläufe", "tabellarische Übersicht über Schule, Ausbildung und Berufserfahrung"], ["das Anschreiben, die Anschreiben", "Brief, in dem man erklärt, warum man die Stelle möchte"], ["das Zeugnis, die Zeugnisse", "offizielles Dokument mit Noten oder einer Bewertung vom Arbeitgeber"], ["die Anzeige, die Anzeigen", "Text in der Zeitung oder im Internet: Eine Firma sucht Mitarbeitende."], ["die Pflegekraft, die Pflegekräfte", "Person, die kranke oder alte Menschen betreut"], ["zuverlässig", "Auf diese Person kann man sich verlassen."], ["das Vorstellungsgespräch, die Vorstellungsgespräche", "Treffen mit der Firma, bevor man eingestellt wird"], ["Teilzeit / Vollzeit", "weniger als / ungefähr 38 bis 40 Stunden pro Woche arbeiten"], ["die Stärke / die Schwäche", "was man gut kann / was man noch nicht so gut kann"], ["die Zusage, die Zusagen", "positive Antwort: Sie bekommen die Stelle."], ["verdienen", "Geld für Arbeit bekommen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["ich schreibe eine Bewerbung, weil es um meine ___ geht.", "Ich habe in der Anzeige gelesen, dass sie ___ suchen,", "Ich bügle mein ___ und übe jeden Satz,", "Im Gespräch fragt die ___, warum ich hier bin.", "___ mein Deutsch nicht perfekt ist, lerne ich jeden Tag,"], "solutions": ["Zukunft", "Pflegekräfte", "Hemd", "Chefin", "Obwohl"]}, "suno": "967c84df-bfdc-455a-87db-c0676a2eaaa2"}, {"id": "b1-02-termin-beim-amt", "level": "B1", "title": "Bitte warten", "theme": "Behörden: Bürgeramt, Ummeldung, Formulare, Dokumente", "grammar": "Passiv Präsens (wird/werden + Partizip II)", "intro": "Wartenummer ziehen, Formular ausfüllen, Stempel holen – kennst du das? Dieser ironische Funk-Song nimmt dich mit aufs Amt und trainiert das Passiv.", "lyrics": "[Verse 1]\nMontagmorgen, sieben Uhr, ich stehe vor dem Amt,\ndie Schlange ist schon lang – ich bin hellwach und angespannt.\nIch ziehe eine Nummer: Zweihundertneun,\nauf dem Bildschirm steht noch: Hundertneun.\n\n[Chorus]\nHier wird gewartet, hier wird gestempelt,\nhier wird gefragt, kopiert und abgeheftet.\nHier werden Formulare ausgefüllt und unterschrieben –\nund am Ende bin ich trotzdem freundlich geblieben.\n\n[Verse 2]\nEndlich bin ich dran: „Zimmer vierzehn, bitte sehr!“\n„Meine Adresse hat sich geändert – ich wohne dort nicht mehr.“\n„Kein Problem“, sagt der Beamte, „das wird sofort gemacht,\nauf Ihren Ausweis wird ein Aufkleber geklebt – so einfach, wer hätte das gedacht?“\n\n[Chorus]\nHier wird gewartet, hier wird gestempelt,\nhier wird gefragt, kopiert und abgeheftet.\nHier werden Formulare ausgefüllt und unterschrieben –\nund am Ende bin ich trotzdem freundlich geblieben.\n\n[Verse 3]\n„Nur eins fehlt noch“, sagt er, „das tut mir wirklich leid:\nDie Bestätigung vom Vermieter wird noch benötigt – Sie haben dafür zwei Wochen Zeit.“\n\n[Bridge]\nIch atme tief ein und ich atme aus,\nich hole das Papier und laufe schnell nach Haus.\nAm nächsten Tag bin ich wieder hier –\nNummer zweihundertzehn – und diesmal klappt es mit mir!\n\n[Chorus]\nHier wird gewartet, hier wird gestempelt,\nhier wird gefragt, kopiert und abgeheftet.\nHier werden Formulare ausgefüllt und unterschrieben –\nund am Ende bin ich trotzdem freundlich geblieben.\n\n[Outro]\nAlles wird erledigt – irgendwann.\nBitte warten. Bitte warten.", "vocab": [["das Amt, die Ämter", "staatliches Büro, z. B. das Bürgeramt"], ["die Schlange, die Schlangen", "hier: viele Menschen, die hintereinander warten"], ["eine Nummer ziehen", "am Automaten ein Papier mit einer Wartenummer nehmen"], ["das Formular, die Formulare", "offizielles Papier mit Feldern für Name, Adresse usw."], ["ausfüllen", "die leeren Felder in einem Dokument beschriften"], ["unterschreiben", "seinen Namen mit der Hand unter ein Dokument setzen"], ["stempeln", "ein offizielles Zeichen mit Farbe auf ein Dokument drücken"], ["der Beamte, die Beamten (ein Beamter)", "Person, die für den Staat arbeitet, z. B. im Bürgeramt"], ["der Ausweis, die Ausweise", "Dokument mit Foto, das zeigt, wer man ist"], ["abheften", "Papiere in einen Ordner legen"], ["benötigen", "brauchen (formell)"], ["erledigen", "eine Aufgabe fertig machen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich ziehe eine ___: Zweihundertneun,", "Hier werden Formulare ___ und unterschrieben –", "„Meine ___ hat sich geändert – ich wohne dort nicht mehr.“", "auf Ihren Ausweis wird ein ___ geklebt – so einfach, wer hätte das gedacht?“", "Ich atme ___ ein und ich atme aus,"], "solutions": ["Nummer", "ausgefüllt", "Adresse", "Aufkleber", "tief"]}, "suno": "794b6a6b-8b28-4223-b2a0-04b302fbe879"}, {"id": "b1-03-kleine-schritte", "level": "B1", "title": "Kleine Schritte", "theme": "Umwelt und Klimaschutz im Alltag", "grammar": "Konjunktiv II: Wünsche (Ich wünschte, …), irreale Bedingungen (Wenn …, würde …), Ratschläge (An deiner Stelle würde ich …, Du solltest …)", "intro": "Was kann ein einzelner Mensch für die Umwelt tun? Dieser hoffnungsvolle Folk-Song gibt Antworten – und du übst Wünsche und Ratschläge im Konjunktiv II.", "lyrics": "[Verse 1]\nIch stehe morgens an der Ruhr, das Wasser fließt so still,\nich frage mich, was ich für diese Erde tun kann und tun will.\nIch fahre mit dem Fahrrad, das Auto bleibt zu Haus,\nich trenne meinen Müll – Papier, Glas, Bio – und bringe ihn raus.\n\n[Chorus]\nKleine Schritte, große Sachen,\nich wünschte, alle würden mitmachen!\nWenn ich die Welt verändern könnte,\nwürde ich bei mir beginnen –\ndenn jeder kleine Schritt zählt,\nund gemeinsam können wir gewinnen.\n\n[Verse 2]\nIm Winter gibt es Erdbeeren, geflogen um die halbe Welt,\nich kaufe lieber regional – das spart CO2 und auch Geld.\nMein Nachbar sagt: „Was bringt das schon? Du allein bist viel zu klein.“\nIch sage: „Wenn alle so denken würden, würde nie etwas anders sein.“\n\n[Chorus]\nKleine Schritte, große Sachen,\nich wünschte, alle würden mitmachen!\nWenn ich die Welt verändern könnte,\nwürde ich bei mir beginnen –\ndenn jeder kleine Schritt zählt,\nund gemeinsam können wir gewinnen.\n\n[Bridge]\nAn deiner Stelle würde ich öfter Bahn fahren,\nan deiner Stelle würde ich Wasser und Strom sparen.\nDu solltest nicht alles kaufen, was die Werbung dir verspricht –\ndie Erde brauchen wir, einen Planeten B gibt es nicht.\n\n[Chorus]\nKleine Schritte, große Sachen,\nich wünschte, alle würden mitmachen!\nWenn ich die Welt verändern könnte,\nwürde ich bei mir beginnen –\ndenn jeder kleine Schritt zählt,\nund gemeinsam können wir gewinnen.", "vocab": [["die Umwelt", "Natur, Luft, Wasser und Boden um uns herum"], ["den Müll trennen", "Papier, Glas, Plastik und Bioabfall in verschiedene Tonnen werfen"], ["regional", "aus der Nähe, aus der eigenen Gegend"], ["das CO2 (Kohlendioxid)", "Gas, das beim Verbrennen von Benzin oder Kohle entsteht und das Klima erwärmt"], ["sparen", "weniger verbrauchen oder ausgeben"], ["die Werbung", "Reklame: Firmen zeigen Produkte, damit man sie kauft"], ["versprechen", "sagen, dass etwas sicher passiert"], ["an deiner Stelle", "wenn ich du wäre"], ["der Planet, die Planeten", "Himmelskörper wie die Erde oder der Mars"], ["verändern", "anders machen"], ["mitmachen", "bei einer Aktion dabei sein und helfen"], ["der Strom", "Energie aus der Steckdose"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich fahre mit dem ___, das Auto bleibt zu Haus,", "ich ___ meinen Müll – Papier, Glas, Bio – und bringe ihn raus.", "ich wünschte, alle würden ___!", "ich kaufe lieber ___ – das spart CO2 und auch Geld.", "an deiner Stelle würde ich Wasser und ___ sparen."], "solutions": ["Fahrrad", "trenne", "mitmachen", "regional", "Strom"]}, "suno": "86e74151-b1fc-47a8-9324-8220ab24be3b"}, {"id": "b1-04-lass-uns-reden", "level": "B1", "title": "Lass uns reden", "theme": "Freundschaft und Konflikte: Streit, Entschuldigung, Versöhnung", "grammar": "Relativsätze (Relativpronomen im Nominativ, Akkusativ, Dativ, mit Präposition)", "intro": "Ein Streit unter Freunden – und dann? Dieses Pop-Rock-Duett erzählt von Streit und Versöhnung. Du übst dabei Relativsätze.", "lyrics": "[Verse 1]\nDu bist die Freundin, die immer für mich da war,\ndie mit mir gelacht und geweint hat, Jahr für Jahr.\nDoch letzte Woche hast du etwas gesagt,\ndas mich verletzt hat – ich habe nicht nachgefragt.\nIch habe geschwiegen, ich war sauer und gekränkt,\nund dachte an die Jahre, die das Leben uns schenkt.\n\n[Chorus]\nLass uns reden, lass uns ehrlich sein,\nein Streit ist doch kein Grund, allein zu sein.\nDu bist der Mensch, dem ich vertraue,\ndie Brücke, auf die ich baue.\n\n[Verse 2]\nIch habe auch gemerkt, dass ich zu laut war,\ndie Worte, die ich sagte, waren unfair – das ist mir jetzt klar.\nWeißt du noch, das Café, in dem wir immer saßen,\nin dem wir die ganze Welt und auch die Zeit vergaßen?\n\n[Chorus]\nLass uns reden, lass uns ehrlich sein,\nein Streit ist doch kein Grund, allein zu sein.\nDu bist der Mensch, dem ich vertraue,\ndie Brücke, auf die ich baue.\n\n[Bridge]\nEs tut mir leid. – Mir tut es auch leid.\nIch habe dich vermisst, die ganze Zeit.\nFreunde, mit denen man streiten kann,\nsind Freunde, die bleiben – von jetzt an.\n\n[Chorus]\nLass uns reden, lass uns ehrlich sein,\nein Streit ist doch kein Grund, allein zu sein.\nDu bist der Mensch, dem ich vertraue,\ndie Brücke, auf die ich baue.\n\n[Outro]\nDu bist der Mensch, dem ich vertraue.", "vocab": [["der Streit, die Streitigkeiten", "lauter Konflikt, Meinungsverschiedenheit"], ["verletzen", "hier: jemandem mit Worten wehtun"], ["sauer sein (ugs.)", "wütend, verärgert sein"], ["gekränkt", "traurig, weil jemand etwas Böses gesagt oder getan hat"], ["schweigen", "nichts sagen, still sein"], ["ehrlich", "offen, die Wahrheit sagend"], ["vertrauen (+ Dativ)", "sicher sein, dass jemand nichts Böses tut"], ["auf jemanden bauen", "sich auf jemanden verlassen"], ["merken", "etwas wahrnehmen, plötzlich verstehen"], ["die Brücke, die Brücken", "Weg über einen Fluss; hier: Verbindung zwischen Menschen"], ["vergessen (vergaß, hat vergessen)", "nicht mehr an etwas denken"], ["sich entschuldigen", "sagen: Es tut mir leid."]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Du bist die ___, die immer für mich da war,", "das mich ___ hat – ich habe nicht nachgefragt.", "Du bist der Mensch, ___ ich vertraue,", "Weißt du noch, das ___, in dem wir immer saßen,", "Freunde, mit ___ man streiten kann,"], "solutions": ["Freundin", "verletzt", "dem", "Café", "denen"]}, "suno": "6c9d3ac3-84f9-4b25-988d-85ff256835f8"}, {"id": "b1-05-zwei-zuhause", "level": "B1", "title": "Zwei Zuhause", "theme": "Heimat und Ankommen: Erinnerungen, Familie im Herkunftsland, neues Leben im Ruhrgebiet", "grammar": "Konjunktiv II für Wünsche (Wenn ich doch …, Ich wünschte …, Ich hätte gern …); temporale Nebensätze mit als und seit", "intro": "Was ist Heimat – ein Ort oder ein Gefühl? Diese berührende Ballade erzählt vom Ankommen im Ruhrgebiet. Du übst Wünsche im Konjunktiv II und Sätze mit als und seit.", "lyrics": "[Verse 1]\nAls ich ankam, war der Himmel grau,\nich kannte keine Wörter, keinen Weg – ich wusste nichts genau.\nSeit ich hier bin, ist so viel passiert,\nich habe gelernt, gearbeitet, gekämpft und viel probiert.\n\n[Chorus]\nIch habe zwei Zuhause, zwei Sprachen in mir,\nein Teil von mir ist dort, ein Teil ist hier.\nWenn ich doch Flügel hätte, wäre ich morgens bei dir\nund abends wieder hier.\n\n[Verse 2]\nMeine Mutter ruft mich an und fragt: „Geht es dir gut?“\nIch sage: „Ja, Mama“ – doch manchmal fehlt mir der Mut.\nIch hätte gern ihr Essen, ihren Tee und ihren Rat\nund den Markt am Morgen in meiner alten Stadt.\n\n[Chorus]\nIch habe zwei Zuhause, zwei Sprachen in mir,\nein Teil von mir ist dort, ein Teil ist hier.\nWenn ich doch Flügel hätte, wäre ich morgens bei dir\nund abends wieder hier.\n\n[Verse 3]\nDoch hier habe ich Freunde, eine Arbeit und ein Ziel,\ndie Nachbarin sagt „Glück auf!“ – und das bedeutet viel.\nIch wünschte, du könntest sehen, wie ich lebe und lache,\nund dass ich jetzt auf Deutsch träume – und manchmal Fehler mache.\n\n[Bridge]\nHeimat ist kein Ort, Heimat ist ein Gefühl,\nmal ist es warm und mal ist es kühl.\nHeimat ist dort, wo man mich versteht,\nwo jemand auf mich wartet, wenn es spät ist.\n\n[Outro]\nZwei Zuhause … und ein Herz.", "vocab": [["ankommen (kam an, ist angekommen)", "an einem neuen Ort eintreffen; hier auch: sich einleben"], ["die Heimat", "Ort oder Land, aus dem man kommt oder wo man sich zu Hause fühlt"], ["der Flügel, die Flügel", "Teil von einem Vogel oder Flugzeug zum Fliegen"], ["der Rat", "Tipp, Empfehlung von einer anderen Person"], ["das Ziel, die Ziele", "das, was man erreichen möchte"], ["Glück auf!", "traditioneller Gruß der Bergleute im Ruhrgebiet"], ["das Gefühl, die Gefühle", "Emotion, z. B. Freude, Angst oder Liebe"], ["kämpfen", "hier: sich sehr anstrengen, um etwas zu schaffen"], ["probieren", "etwas Neues versuchen oder testen"], ["träumen", "im Schlaf Bilder sehen; sich etwas sehr wünschen"], ["der Mut", "innere Stärke, keine Angst haben"], ["seit", "von einem Zeitpunkt in der Vergangenheit bis jetzt"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Als ich ankam, war der Himmel ___,", "___ ich hier bin, ist so viel passiert,", "Wenn ich doch ___ hätte, wäre ich morgens bei dir", "die ___ sagt „Glück auf!“ – und das bedeutet viel.", "Heimat ist kein Ort, Heimat ist ein ___,"], "solutions": ["grau", "Seit", "Flügel", "Nachbarin", "Gefühl"]}, "suno": "ada65927-853a-49ab-8e9f-28a1dcb3fe58"}, {"id": "b2-01-montagsmeeting", "level": "B2", "title": "Montagsmeeting", "theme": "Teamarbeit und Meetings: Aufgaben, Verantwortung, Fristen", "grammar": "Passiv mit Modalverb (muss erledigt werden, könnten verteilt werden)", "intro": "Montag, neun Uhr, Konferenzraum drei: Keiner fühlt sich zuständig. Dieser Synth-Pop-Song zeigt, wie aus Chaos Teamarbeit wird – mit viel Passiv mit Modalverb.", "lyrics": "[Verse 1]\nMontag, neun Uhr, Konferenzraum drei,\nder Beamer brummt, der Kaffee ist kalt – und alle sind dabei.\nDie Chefin teilt die Tagesordnung aus, Punkt für Punkt,\ndas Projekt hängt hinterher – und keiner kennt den Grund.\n\n[Pre-Chorus]\nDer Bericht muss bis Freitag fertiggestellt werden,\ndie Zahlen müssen noch geprüft werden,\nder Kunde soll heute noch informiert werden –\ndoch wer macht das? Alle schauen auf ihre Bildschirme.\n\n[Chorus]\nDas muss erledigt werden – aber wer fängt an?\nDas kann geschafft werden, wenn jeder gibt, was er kann.\nEin Team ist mehr als jeder Einzelne allein,\nwir müssen nicht perfekt, nur ehrlich miteinander sein.\n\n[Verse 2]\nHerr Krämer sagt: „Das stand nicht in meiner Mail!“\nFrau Yilmaz seufzt: „Dann haben wir ein Problem – und zwar im Detail.“\nDie Verantwortung wird hin- und hergeschoben,\nund das Problem wird wieder auf nächste Woche verschoben.\n\n[Chorus]\nDas muss erledigt werden – aber wer fängt an?\nDas kann geschafft werden, wenn jeder gibt, was er kann.\nEin Team ist mehr als jeder Einzelne allein,\nwir müssen nicht perfekt, nur ehrlich miteinander sein.\n\n[Bridge]\nDann sagt die Neue leise: „Darf ich etwas vorschlagen?\nDie Aufgaben könnten fair verteilt werden, dann muss keiner alles tragen.\nEin Board an der Wand, zehn Minuten jeden Tag:\nWer macht was bis wann – und wer braucht noch einen Rat?“\nAlle schauen sich an, dann nickt die Chefin: „So wird’s gemacht.“\nZum ersten Mal seit Wochen wird im Meeting gelacht.\n\n[Outro]\nDas kann geschafft werden – Hand in Hand.", "vocab": [["die Tagesordnung, die Tagesordnungen", "Liste der Themen, die in einer Sitzung besprochen werden"], ["hinterherhängen (ugs.)", "langsamer sein als geplant, im Rückstand sein"], ["fertigstellen", "eine Arbeit abschließen, vollenden"], ["der Bericht, die Berichte", "schriftliche Darstellung von Ergebnissen oder Ereignissen"], ["prüfen", "kontrollieren, ob etwas korrekt ist"], ["die Verantwortung", "die Pflicht, für eine Aufgabe und ihre Folgen einzustehen"], ["etwas hin- und herschieben", "hier: eine Aufgabe immer an andere weitergeben"], ["verschieben", "auf einen späteren Zeitpunkt legen"], ["vorschlagen", "eine Idee oder Lösung anbieten"], ["verteilen", "aufteilen und an mehrere Personen geben"], ["die Frist, die Fristen", "Zeitpunkt, bis zu dem etwas fertig sein muss"], ["nicken", "den Kopf kurz nach unten bewegen, um Zustimmung zu zeigen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Der Bericht muss bis Freitag ___ werden,", "die Zahlen müssen noch ___ werden,", "Das kann geschafft werden, wenn jeder ___, was er kann.", "und das Problem wird wieder auf nächste Woche ___.", "Die Aufgaben könnten fair ___ werden, dann muss keiner alles tragen."], "solutions": ["fertiggestellt", "geprüft", "gibt", "verschoben", "verteilt"]}, "suno": "5f30763c-3eea-4475-9c08-3f312ac8bc1b"}, {"id": "b2-02-ihr-anliegen", "level": "B2", "title": "Ihr Anliegen ist uns wichtig", "theme": "Kundenkontakt und Beschwerde: Reklamation, Deeskalation, Lösungen", "grammar": "Redemittel für Beschwerde und Reaktion; Konjunktiv II der Höflichkeit (Könnten Sie …? Ich wäre Ihnen dankbar, wenn …); zweiteilige Konnektoren (entweder … oder, nicht nur … sondern auch)", "intro": "Eine Waschmaschine, die nie kommt, und ein Kundenservice unter Druck: Dieses Swing-Duett zeigt, wie man sich höflich, aber bestimmt beschwert – und wie man professionell reagiert.", "lyrics": "[Verse 1]\nIch habe vor drei Wochen eine Waschmaschine bestellt,\ngeliefert wurde nichts – doch abgebucht wurde mein Geld!\nIch habe angerufen, geschrieben, gehofft,\nin Ihrer Warteschleife hing ich stundenlang – und das oft.\nIch möchte mich beschweren, und zwar in aller Form:\nIhr Service ist, mit Verlaub, eine Zumutung – enorm!\n\n[Chorus]\n„Ich verstehe Ihren Ärger, das tut mir wirklich leid,\nich kümmere mich persönlich drum – es dauert keine Ewigkeit.\nIhr Anliegen ist uns wichtig, wir finden einen Weg,\ndamit Ihre Zufriedenheit wieder an erster Stelle steht.“\n\n[Verse 2]\n„Das hat man mir zweimal versprochen – und nichts ist passiert.\nEntweder kommt die Maschine bis Freitag, oder der Kauf wird storniert!\nKönnten Sie mir bitte sagen, wer dafür verantwortlich ist?\nIch wäre Ihnen dankbar, wenn das schnell geklärt würde – das ist eine faire Frist.“\n\n[Chorus]\n„Ich verstehe Ihren Ärger, das tut mir wirklich leid,\nich kümmere mich persönlich drum – es dauert keine Ewigkeit.\nIhr Anliegen ist uns wichtig, wir finden einen Weg,\ndamit Ihre Zufriedenheit wieder an erster Stelle steht.“\n\n[Verse 3]\n„Ich würde Ihnen Folgendes vorschlagen: Die Lieferung erfolgt am Mittwoch früh,\ndie Versandkosten werden erstattet – für Ihre Geduld und Ihre Müh’.\nUnd Sie bekommen einen Gutschein, nicht nur als Entschuldigung, sondern auch als Dank,\nweil Sie uns treu geblieben sind, obwohl Sie warten mussten – viel zu lang.“\n\n[Bridge]\n„Na gut“, sagt sie, „das klingt fair, ich bin einverstanden.“\n„Wir danken Ihnen – schön, dass wir gemeinsam eine Lösung fanden.“\nAm Mittwoch um acht klingelt es – die Maschine ist da,\nund die Kundin lacht: „Na also, geht doch – wunderbar!“", "vocab": [["sich beschweren (über + Akk.)", "deutlich sagen, dass man mit etwas unzufrieden ist"], ["abbuchen", "Geld automatisch vom Konto nehmen"], ["die Warteschleife, die Warteschleifen", "am Telefon: Man wartet mit Musik, bis jemand antwortet"], ["die Zumutung, die Zumutungen", "etwas, das man nicht akzeptieren kann, weil es zu viel verlangt"], ["mit Verlaub (geh.)", "höfliche Einleitung vor einer offenen, kritischen Aussage"], ["das Anliegen, die Anliegen", "Wunsch, Bitte oder Problem, das man vorbringt"], ["sich kümmern um (+ Akk.)", "für eine Sache sorgen, sie erledigen"], ["stornieren", "einen Auftrag oder eine Buchung rückgängig machen"], ["erstatten", "Geld zurückzahlen"], ["die Versandkosten (Pl.)", "Kosten für das Verschicken einer Ware"], ["der Gutschein, die Gutscheine", "Papier oder Code mit einem Geldwert für einen späteren Einkauf"], ["einverstanden sein", "zustimmen, etwas akzeptieren"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["geliefert wurde nichts – doch ___ wurde mein Geld!", "in Ihrer ___ hing ich stundenlang – und das oft.", "Entweder kommt die Maschine bis Freitag, oder der Kauf wird ___!", "Ich wäre Ihnen ___, wenn das schnell geklärt würde – das ist eine faire Frist.“", "die Versandkosten werden ___ – für Ihre Geduld und Ihre Müh’."], "solutions": ["abgebucht", "Warteschleife", "storniert", "dankbar", "erstattet"]}, "suno": "bbdcc6c2-b283-464e-8d0c-35740db927ea"}, {"id": "b2-03-immer-online", "level": "B2", "title": "Immer online", "theme": "Digitalisierung: Arbeit, Alltag, ständige Erreichbarkeit, digitale Pausen", "grammar": "Nominalisierung (das Erreichen, die Abschaltung, die Erreichbarkeit); Redemittel Meinung (Meiner Meinung nach …, Ich bin der Ansicht, dass …); einerseits … andererseits", "intro": "Verbunden mit der ganzen Welt – und trotzdem allein? Dieser Synthwave-Song denkt über die Digitalisierung nach. Du übst Nominalisierungen und Redemittel, um deine Meinung zu sagen.", "lyrics": "[Verse 1]\nMein Wecker ist ein Handy, mein Gedächtnis eine Cloud,\nmeine Uhr zählt jeden Schritt – ich habe ihr blind vertraut.\nDie Digitalisierung der Arbeit kam schneller als gedacht:\nVideokonferenzen am Morgen, E-Mails bis in die Nacht.\n\n[Pre-Chorus]\nDas Erreichen aller Ziele, das Optimieren jeder Zeit,\ndas Vernetzen aller Dinge – sind wir dafür bereit?\n\n[Chorus]\nIch bin online, immer online,\nverbunden mit der ganzen Welt – und trotzdem allein.\nZwischen Fortschritt und Überforderung\nsuche ich die Balance, eine neue Ordnung.\n\n[Verse 2]\nEinerseits ist vieles leichter: ein Klick, ein Formular,\ndie Arbeit von zu Hause aus – für viele ein Gewinn, ganz klar.\nAndererseits raubt mir die ständige Erreichbarkeit\nden Schlaf, die Konzentration und ein großes Stück Freiheit.\n\n[Chorus]\nIch bin online, immer online,\nverbunden mit der ganzen Welt – und trotzdem allein.\nZwischen Fortschritt und Überforderung\nsuche ich die Balance, eine neue Ordnung.\n\n[Verse 3]\nMeiner Meinung nach liegt das Problem nicht in der Technik selbst,\nsondern darin, ob du die Kontrolle in den Händen hältst.\nIch bin der Ansicht, dass wir Grenzen ziehen müssen, klar und fest:\neine Stunde ohne Bildschirm – ein kleines digitales Fest.\n\n[Bridge]\nDie Abschaltung der Geräte um zehn,\ndas Lesen von Büchern, das Spazierengehen ohne Ziel – wie schön.\nDas Zuhören, das Schweigen, das Sehen –\nmanchmal muss man offline gehen.\n\n[Chorus]\nIch bin online, immer online,\nverbunden mit der ganzen Welt – und trotzdem allein.\nZwischen Fortschritt und Überforderung\nsuche ich die Balance, eine neue Ordnung.\n\n[Outro]\nOffline … nur für einen Moment.", "vocab": [["die Digitalisierung", "Umstellung von analogen auf digitale Prozesse und Technologien"], ["die Cloud, die Clouds", "Speicherplatz für Daten im Internet"], ["blind vertrauen", "jemandem ohne Kontrolle oder Zweifel glauben"], ["die Videokonferenz, die Videokonferenzen", "Besprechung über Kamera und Internet"], ["vernetzen", "Geräte oder Menschen miteinander verbinden"], ["der Fortschritt, die Fortschritte", "Entwicklung zu etwas Besserem oder Modernerem"], ["die Überforderung", "Zustand, wenn Aufgaben zu viel oder zu schwer sind"], ["die ständige Erreichbarkeit", "immer per Handy oder Mail kontaktierbar sein"], ["rauben", "hier: wegnehmen"], ["Grenzen ziehen", "klar festlegen, was man nicht mehr tun oder akzeptieren will"], ["der Bildschirm, die Bildschirme", "Monitor oder Display von Handy, Laptop oder Fernseher"], ["einerseits … andererseits", "Konnektor: zeigt zwei Seiten einer Sache"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Die ___ der Arbeit kam schneller als gedacht:", "Zwischen Fortschritt und ___", "Andererseits raubt mir die ständige ___", "sondern darin, ob du die ___ in den Händen hältst.", "Ich bin der Ansicht, dass wir ___ ziehen müssen, klar und fest:"], "solutions": ["Digitalisierung", "Überforderung", "Erreichbarkeit", "Kontrolle", "Grenzen"]}, "suno": "44c8d365-d480-467a-86e4-64c6db5b7833"}, {"id": "b2-04-feierabend", "level": "B2", "title": "Feierabend", "theme": "Work-Life-Balance: Überstunden, Erholung, Grenzen setzen, Gespräch mit der Chefin", "grammar": "Zweiteilige Konnektoren (zwar … aber, sowohl … als auch, je … desto, weder … noch, nicht nur … sondern auch, entweder … oder)", "intro": "Laptop zu, Feierabend! Dieser entspannte Reggae-Song erzählt, wie man aus dem Hamsterrad aussteigt – und trainiert ganz nebenbei alle wichtigen zweiteiligen Konnektoren.", "lyrics": "[Verse 1]\nZwar liebe ich meinen Job, aber nicht um jeden Preis,\nich drehe mich wie ein Hamster im ewigen Kreis.\nIch arbeite sowohl am Tag als auch oft in der Nacht\nund habe seit Wochen nicht mehr richtig gelacht.\n\n[Pre-Chorus]\nJe mehr ich mache, desto mehr kommt dazu,\nje länger ich bleibe, desto weniger finde ich Ruh’.\n\n[Chorus]\nFeierabend, Feierabend – der Laptop geht zu,\ndie Welt kann warten, jetzt bin ich dran – und du.\nWeder Mails noch Anrufe nach sechs Uhr,\nnur Sonne, Musik und ein Spaziergang durch die Natur.\n\n[Verse 2]\nMein Kollege sagt: „Wer früh geht, kommt nicht weit.“\nIch sage: „Wer nie Pause macht, brennt aus mit der Zeit.“\nNicht nur mein Körper braucht Erholung, sondern auch mein Kopf,\nsonst kocht der Druck irgendwann über wie Wasser im Topf.\n\n[Chorus]\nFeierabend, Feierabend – der Laptop geht zu,\ndie Welt kann warten, jetzt bin ich dran – und du.\nWeder Mails noch Anrufe nach sechs Uhr,\nnur Sonne, Musik und ein Spaziergang durch die Natur.\n\n[Verse 3]\nEntweder ich ändere was, oder es ändert sich nie,\nalso plane ich jetzt Pausen – mit Strategie.\nIch habe mit meiner Chefin gesprochen, ehrlich und direkt,\nund sie hat gesagt: „Danke, dass Sie das ansprechen – wir haben das zu spät entdeckt.“\n\n[Bridge]\nMittwochs Homeoffice, freitags früher Schluss,\nkein schlechtes Gewissen, kein Stress, kein Muss.\nJe ruhiger ich bin, desto besser arbeite ich auch –\ndas ist kein Luxus, das ist, was ich brauch’.\n\n[Outro]\nFeierabend … jetzt bin ich dran.", "vocab": [["der Feierabend", "Ende des Arbeitstages; die freie Zeit danach"], ["um jeden Preis", "egal, was es kostet; unbedingt"], ["sich im Kreis drehen", "immer dasselbe tun, ohne weiterzukommen"], ["die Erholung", "Ruhe und Pause, damit man wieder Kraft hat"], ["ausbrennen", "durch zu viel Stress völlig erschöpft werden (Burnout)"], ["der Druck", "hier: Stress, Belastung durch Erwartungen"], ["etwas ansprechen", "ein Thema offen zur Sprache bringen"], ["das schlechte Gewissen", "Gefühl, etwas falsch gemacht zu haben"], ["der Luxus", "etwas Besonderes, das man nicht unbedingt braucht"], ["zwar … aber", "Konnektor: Einschränkung oder Gegensatz"], ["je … desto", "Konnektor: Wenn sich das eine verändert, verändert sich auch das andere."], ["weder … noch", "Konnektor: nicht das eine und auch nicht das andere"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Zwar liebe ich meinen Job, aber nicht um jeden ___,", "Je mehr ich mache, ___ mehr kommt dazu,", "Weder Mails ___ Anrufe nach sechs Uhr,", "Nicht nur mein Körper braucht ___, sondern auch mein Kopf,", "kein schlechtes ___, kein Stress, kein Muss."], "solutions": ["Preis", "desto", "noch", "Erholung", "Gewissen"]}, "suno": "e63b841b-2ff3-4ec5-ad8a-952b5cc8e96e"}, {"id": "b2-05-nachtschicht", "level": "B2", "title": "Nachtschicht", "theme": "Gesundheit im Beruf: Schichtarbeit, Rücken, Erschöpfung, Arbeitsschutz, Teamzusammenhalt", "grammar": "Finalsätze (um … zu, damit) und Konsekutivsätze (so … dass, sodass); ohne … zu", "intro": "Wer andere pflegt, muss auch auf sich selbst achten. Dieser Soul-Song über eine Nachtschicht im Krankenhaus trainiert Sätze mit um … zu, damit und sodass.", "lyrics": "[Verse 1]\nNachtschicht im Krankenhaus, die Flure sind leer,\nmein Rücken tut weh, meine Beine sind schwer.\nIch hebe, ich trage, ich laufe die ganze Nacht\nund habe so oft nicht an mich selbst gedacht.\n\n[Pre-Chorus]\nIch war so müde, dass ich auf dem Heimweg am Steuer fast einschlief –\nda wusste ich: So geht es nicht weiter, irgendwas läuft schief.\n\n[Chorus]\nIch muss auf mich achten, um für andere da zu sein,\nich kann nicht alle retten – und schon gar nicht allein.\nIch brauche Pausen, damit ich wieder lachen kann –\nauch wer andere pflegt, ist selbst irgendwann dran.\n\n[Verse 2]\nDie Betriebsärztin hat gesagt: „So kann es nicht weitergehen.\nSie heben falsch, Sie schlafen zu wenig – das kann ich sehen.\nNutzen Sie die Hebehilfe, um den Rücken zu schonen,\nund gönnen Sie sich Ruhe – das wird sich lohnen.“\n\n[Chorus]\nIch muss auf mich achten, um für andere da zu sein,\nich kann nicht alle retten – und schon gar nicht allein.\nIch brauche Pausen, damit ich wieder lachen kann –\nauch wer andere pflegt, ist selbst irgendwann dran.\n\n[Verse 3]\nWir haben im Team besprochen, wie wir uns gegenseitig stützen\nund wie wir unsere Pausen in Zukunft besser schützen.\nKeiner springt mehr ein, ohne zu fragen, ob es geht,\nsodass nicht mehr nur einer bis zum Umfallen am Bett steht.\n\n[Bridge]\nErschöpfung ist kein Zeichen von Stärke,\nund Schlafmangel ist kein Beweis für gute Werke.\nWer dauerhaft über seine Grenzen geht,\nmerkt oft erst zu spät, was auf dem Spiel steht.\n\n[Outro]\nUm für andere da zu sein,\nmuss ich auf mich achten.", "vocab": [["die Nachtschicht, die Nachtschichten", "Arbeitszeit in der Nacht, z. B. von 21 bis 6 Uhr"], ["etwas läuft schief (ugs.)", "etwas funktioniert nicht so, wie es sollte"], ["auf sich achten", "gut für die eigene Gesundheit sorgen"], ["pflegen", "kranke oder alte Menschen betreuen und versorgen"], ["die Betriebsärztin, die Betriebsärztinnen", "Ärztin, die sich um die Gesundheit der Beschäftigten eines Unternehmens kümmert"], ["die Hebehilfe, die Hebehilfen", "Gerät, mit dem man Patienten ohne große Kraft bewegt"], ["schonen", "vorsichtig behandeln, nicht belasten"], ["sich etwas gönnen", "sich bewusst etwas Gutes erlauben"], ["einspringen", "kurzfristig für eine Kollegin oder einen Kollegen arbeiten"], ["bis zum Umfallen (ugs.)", "bis man vor Erschöpfung nicht mehr kann"], ["die Erschöpfung", "Zustand völliger Müdigkeit und Kraftlosigkeit"], ["auf dem Spiel stehen", "in Gefahr sein, verloren zu gehen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["mein ___ tut weh, meine Beine sind schwer.", "Ich muss auf mich ___, um für andere da zu sein,", "Nutzen Sie die Hebehilfe, um den Rücken zu ___,", "Keiner ___ mehr ein, ohne zu fragen, ob es geht,", "___ ist kein Zeichen von Stärke,"], "solutions": ["Rücken", "achten", "schonen", "springt", "Erschöpfung"]}, "suno": "c8fb898d-da1a-4035-b120-61c7e328a384"}, {"id": "c1-01-zwischen-den-zeilen", "level": "C1", "title": "Zwischen den Zeilen", "theme": "Sprache und Identität: Mehrsprachigkeit, Akzent, Zugehörigkeit", "grammar": "Erweiterte Partizipialattribute (die mühsam gelernten Regeln, ein langsam wachsender Garten)", "intro": "Wie fühlt es sich an, in einer Sprache zu leben, in der man nicht geboren ist? Dieses poetische Chanson spielt mit Bildern für Mehrsprachigkeit – und mit erweiterten Partizipialattributen.", "lyrics": "[Verse 1]\nIch trage eine Sprache, in der ich nicht geboren bin,\ndie mir geliehenen Wörter geben meinem Leben neuen Sinn.\nDie mühsam auswendig gelernten Regeln liegen schwer auf meiner Zunge,\ndoch jedes neu entdeckte Wort füllt mir wie Luft die Lunge.\n\n[Pre-Chorus]\nDer, die, das – ein nie endender Tanz,\ndoch ein falsch gesetzter Artikel nimmt mir nicht den Glanz.\n\n[Chorus]\nIch lebe zwischen den Zeilen, zwischen hier und dort,\nin jedem übersetzten Satz verliere ich ein Wort,\nund finde dafür ein neues, das nach Heimat klingt –\nein in zwei Sprachen geträumtes Lied, das in mir singt.\n\n[Verse 2]\nMeine Großmutter sprach in Bildern, die kein Wörterbuch kennt,\nein nie ganz erloschenes Feuer, das noch in mir brennt.\nMan lobt mich: „Sie sprechen ja fast ohne Akzent!“ –\nals wäre meine Herkunft ein Makel, den man zum Glück nicht mehr erkennt.\n\n[Chorus]\nIch lebe zwischen den Zeilen, zwischen hier und dort,\nin jedem übersetzten Satz verliere ich ein Wort,\nund finde dafür ein neues, das nach Heimat klingt –\nein in zwei Sprachen geträumtes Lied, das in mir singt.\n\n[Verse 3]\nIch will nicht aufgehen in einer glatt polierten Norm,\nmein Deutsch hat Ecken und Kanten – und gerade das gibt ihm Form.\nDie Sprache ist ein Haus mit vielen offenen Türen,\nin jedem darin verbrachten Jahr kann ich es tiefer spüren.\n\n[Bridge]\nSprache ist kein Pass, kein Stempel, kein Beweis,\nsie ist ein langsam wachsender Garten – und er wächst auf meine Weise.\nEin von vielen Stimmen getragenes Ich –\ndas bin ich, das bin ich.\n\n[Outro]\nZwischen den Zeilen … da wohne ich.", "vocab": [["mühsam", "mit viel Anstrengung und Geduld"], ["leihen (lieh, hat geliehen)", "etwas für eine Zeit geben, das später zurückkommen soll"], ["zwischen den Zeilen", "im nicht direkt Gesagten, in der versteckten Bedeutung"], ["erloschen", "nicht mehr brennend (Feuer, Licht); übertragen: vorbei"], ["der Akzent, die Akzente", "besondere Aussprache, an der man die Herkunft hört"], ["der Makel, die Makel", "Fehler oder Schwäche, die negativ auffällt"], ["die Herkunft", "Land, Familie oder Milieu, aus dem jemand stammt"], ["aufgehen in (+ Dat.)", "ganz Teil von etwas werden und sich darin verlieren"], ["die Norm, die Normen", "Regel, Standard, das als normal Geltende"], ["Ecken und Kanten haben", "nicht glatt und angepasst sein, Persönlichkeit zeigen"], ["der Glanz", "Leuchten; übertragen: Ausstrahlung, Würde"], ["der Beweis, die Beweise", "etwas, das zeigt, dass eine Behauptung stimmt"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["die mir ___ Wörter geben meinem Leben neuen Sinn.", "doch jedes neu ___ Wort füllt mir wie Luft die Lunge.", "in jedem ___ Satz verliere ich ein Wort,", "ein nie ganz ___ Feuer, das noch in mir brennt.", "mein Deutsch hat Ecken und ___ – und gerade das gibt ihm Form."], "solutions": ["geliehenen", "entdeckte", "übersetzten", "erloschenes", "Kanten"]}, "suno": "8d74b826-5bfd-440e-933b-976eec4dd73c"}, {"id": "c1-02-ungeschriebene-briefe", "level": "C1", "title": "Ungeschriebene Briefe", "theme": "Erinnerung: Großvater, Bergbau, Strukturwandel im Ruhrgebiet", "grammar": "Plusquamperfekt; Konjunktiv II der Vergangenheit (Hätte ich doch …, Er hätte … gekonnt, wenn …); temporale Nebensätze (nachdem, bevor, als)", "intro": "Ein leeres Zechenhaus, ein Großvater, viele unausgesprochene Fragen: Diese melancholische Piano-Ballade erzählt von Erinnerung und Strukturwandel im Ruhrgebiet. Du übst Plusquamperfekt und Konjunktiv II der Vergangenheit.", "lyrics": "[Verse 1]\nDas Haus in der Siedlung steht noch, die Fenster sind blind,\nim Garten, wo wir Bohnen zogen, spielt jetzt nur der Wind.\nHier hatte mein Großvater nach der Schicht im Schacht gesessen,\nden Kohlenstaub im Gesicht, und Brot mit Schmalz gegessen.\n\n[Verse 2]\nBevor er morgens losging, hatte er mir oft erzählt:\n„Unter Tage, Junge, ist das Licht das, was am meisten fehlt.“\nIch hatte nie verstanden, was in seinen Händen lag:\ndie Härte und die Zärtlichkeit, die Kraft für jeden Tag.\n\n[Chorus]\nHätte ich ihn doch öfter gefragt,\nwäre ich nur länger geblieben!\nErinnerung ist ein Haus mit vielen Zimmern –\nund manche Briefe bleiben ungeschrieben.\n\n[Verse 3]\nAls die Zeche schloss, war er gerade sechzig geworden,\nman gab ihm eine Urkunde – aber keinen neuen Morgen.\nEr hätte noch so viel gekonnt, hätte man ihn nur gelassen,\nstattdessen saß er abends schweigend vor den leeren Tassen.\n\n[Chorus]\nHätte ich ihn doch öfter gefragt,\nwäre ich nur länger geblieben!\nErinnerung ist ein Haus mit vielen Zimmern –\nund manche Briefe bleiben ungeschrieben.\n\n[Bridge]\nWo früher Kohle gefördert wurde, wird heute getanzt,\ndie Halden sind begrünt, und Birken sind gepflanzt.\nIch stehe oben auf der Halde, und ich höre seinen Schritt,\nder Wind trägt seine Stimme – und ich nehme sie mit.\n\n[Chorus]\nHätte ich ihn doch öfter gefragt,\nwäre ich nur länger geblieben!\nErinnerung ist ein Haus mit vielen Zimmern –\nund manche Briefe bleiben ungeschrieben.\n\n[Outro]\nManche Briefe bleiben ungeschrieben …\naber nicht vergessen.", "vocab": [["die Siedlung, die Siedlungen", "Gruppe ähnlicher Häuser, hier für Bergarbeiterfamilien"], ["die Schicht, die Schichten", "festgelegte Arbeitszeit, z. B. Früh- oder Nachtschicht"], ["der Schacht, die Schächte", "senkrechter Tunnel in die Tiefe eines Bergwerks"], ["unter Tage", "unter der Erde, im Bergwerk"], ["der Kohlenstaub", "feine schwarze Teilchen von Kohle"], ["die Zeche, die Zechen", "Bergwerk für Kohle (besonders im Ruhrgebiet)"], ["die Halde, die Halden", "künstlicher Berg aus Gestein vom Bergbau"], ["(Kohle) fördern", "aus der Erde holen, abbauen"], ["die Urkunde, die Urkunden", "offizielles Dokument, z. B. als Anerkennung"], ["die Zärtlichkeit", "liebevolle, sanfte Zuwendung"], ["Bohnen ziehen", "Bohnen im Garten anbauen"], ["ungeschrieben", "nie zu Papier gebracht"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Hier hatte mein Großvater nach der ___ im Schacht gesessen,", "„Unter Tage, Junge, ist das ___ das, was am meisten fehlt.“", "Ich hatte nie ___, was in seinen Händen lag:", "Hätte ich ihn doch ___ gefragt,", "Wo früher Kohle ___ wurde, wird heute getanzt,"], "solutions": ["Schicht", "Licht", "verstanden", "öfter", "gefördert"]}, "suno": "874925b3-692d-4486-b1ab-a2b0169e42b8"}, {"id": "c1-03-wandel-wird-gemacht", "level": "C1", "title": "Wandel wird gemacht", "theme": "Gesellschaft und Wandel: Strukturwandel, soziale Ungleichheit, Vielfalt, Engagement", "grammar": "Nominalstil; Präpositionen mit Genitiv (angesichts, infolge, trotz, aufgrund); Umformung Nebensatz ↔ Nominalgruppe", "intro": "Steigende Mieten, geschlossene Werke, große Versprechen: Dieser Conscious-Rap fragt, wer den Wandel eigentlich gestaltet. Du trainierst Nominalstil und Präpositionen mit Genitiv.", "lyrics": "[Verse 1]\nAngesichts steigender Mieten und sinkender Löhne\nfragt sich meine Nachbarin, ob sie sich je daran gewöhnt.\nInfolge der Schließung des Werkes vor zehn Jahren\nsind die Jungen weggezogen – geblieben sind die mit grauen Haaren.\nTrotz aller Versprechen von Wandel und Neubeginn\nfragen viele: Wo ist für uns darin der Sinn?\nAufgrund fehlender Busse, Ärzte, Läden um die Ecke\nbleibt manches Viertel im wahrsten Sinne auf der Strecke.\n\n[Chorus]\nAlles im Wandel, nichts bleibt, wie es war,\nwer nicht mitkommt, wird übersehen – Jahr für Jahr.\nDoch Wandel ist kein Schicksal, Wandel wird gemacht –\nvon Menschen, die sich einmischen, und zwar mit Bedacht.\n\n[Verse 2]\nDie Förderung von Bildung, die Stärkung der Bindung\nzwischen Alt und Jung – so steht’s in jeder Ankündigung.\nDoch zwischen der Planung und der Umsetzung liegen Jahre,\nin denen manche Idee verstaubt – und das ist nicht das Wahre.\nMeine Oma sagt: „Früher war nicht alles besser, Kind,\nnur langsamer – heute dreht sich alles so geschwind.“\n\n[Chorus]\nAlles im Wandel, nichts bleibt, wie es war,\nwer nicht mitkommt, wird übersehen – Jahr für Jahr.\nDoch Wandel ist kein Schicksal, Wandel wird gemacht –\nvon Menschen, die sich einmischen, und zwar mit Bedacht.\n\n[Verse 3]\nWir sind die Kinder von Gastarbeitern, Bergleuten, Geflüchteten,\ndie Enkel derer, die hier Häuser und Brücken errichteten.\nUnsere Vielfalt ist kein Problem, das gelöst werden muss,\nsondern eine Antwort – und zwar nicht erst zum Schluss.\n\n[Bridge]\nWas wir heute säen, wird morgen erst blühen,\nes lohnt sich, sich zu bemühen.\nEs lohnt sich, sich zu bemühen.\n\n[Chorus]\nAlles im Wandel, nichts bleibt, wie es war,\nwer nicht mitkommt, wird übersehen – Jahr für Jahr.\nDoch Wandel ist kein Schicksal, Wandel wird gemacht –\nvon Menschen, die sich einmischen, und zwar mit Bedacht.\n\n[Outro]\nWandel wird gemacht.", "vocab": [["angesichts (+ Gen.)", "im Hinblick auf; wenn man … betrachtet"], ["infolge (+ Gen.)", "als Folge von"], ["aufgrund (+ Gen.)", "wegen, verursacht durch"], ["auf der Strecke bleiben", "scheitern, nicht mitkommen, vergessen werden"], ["das Schicksal, die Schicksale", "Lauf des Lebens, der scheinbar vorherbestimmt ist"], ["sich einmischen", "aktiv Einfluss nehmen, sich beteiligen"], ["mit Bedacht", "überlegt, sorgfältig"], ["die Umsetzung, die Umsetzungen", "Verwirklichung eines Plans in der Praxis"], ["verstauben", "lange ungenutzt liegen bleiben"], ["nicht das Wahre sein (ugs.)", "nicht wirklich gut, nicht ideal sein"], ["die Vielfalt", "Verschiedenheit, große Zahl unterschiedlicher Formen"], ["errichten", "bauen, aufbauen"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["___ steigender Mieten und sinkender Löhne", "Infolge der ___ des Werkes vor zehn Jahren", "bleibt manches Viertel im wahrsten Sinne auf der ___.", "Doch Wandel ist kein ___, Wandel wird gemacht –", "Unsere ___ ist kein Problem, das gelöst werden muss,"], "solutions": ["Angesichts", "Schließung", "Strecke", "Schicksal", "Vielfalt"]}, "suno": "1946ba08-31af-4d8e-abc5-201fd9fc48d2"}, {"id": "c1-04-ins-kalte-wasser", "level": "C1", "title": "Ins kalte Wasser", "theme": "Mut und Neuanfang: Jobverlust, Selbstständigkeit, Risiko, Durchhalten", "grammar": "Idiomatische Wendungen; irreale Vergleichssätze mit als ob / als + Konjunktiv II", "intro": "Mit vierzig alles hinwerfen und eine Bäckerei eröffnen? Dieser hymnische Indie-Rock-Song steckt voller Redewendungen – und zeigt, dass Mut nicht heißt, keine Angst zu haben.", "lyrics": "[Verse 1]\nIch stand mit dem Rücken zur Wand, der Job war weg, die Kasse leer,\nich tat, als ob mir das nichts ausmachte – doch das Lächeln fiel mir schwer.\nZehn Jahre im selben Büro, im selben Trott, im selben Grau,\nund tief in mir wusste ich es ganz genau.\n\n[Pre-Chorus]\nAlle sagten: „Bleib auf dem Teppich! Spiel nicht mit dem Feuer!\nEin Neuanfang mit vierzig? Das ist uns nicht geheuer!“\n\n[Chorus]\nIch springe ins kalte Wasser, ich wage den ersten Schritt –\nwer nie etwas riskiert, nimmt am Ende nichts vom Leben mit.\nEs ist, als würde ich nach langer Zeit wieder atmen,\nich setze alles auf eine Karte – und lasse die Angst draußen warten.\n\n[Verse 2]\nJetzt backe ich kleine Brötchen – und zwar im wörtlichen Sinn:\neine winzige Bäckerei im Viertel, und ich stehe mittendrin.\nUm vier Uhr früh der Wecker, Mehl in den Haaren, Teig an der Hand,\nso manches ging in die Hose – doch ich warf nie das Handtuch, ich hielt stand.\n\n[Chorus]\nIch springe ins kalte Wasser, ich wage den ersten Schritt –\nwer nie etwas riskiert, nimmt am Ende nichts vom Leben mit.\nEs ist, als würde ich nach langer Zeit wieder atmen,\nich setze alles auf eine Karte – und lasse die Angst draußen warten.\n\n[Verse 3]\nDie Nachbarn kamen zögernd, dann kamen sie in Scharen,\nals hätten sie auf so einen Laden gewartet – seit Jahren.\nIch bin nicht reich geworden, doch ich bin wieder ich,\nund das ist mehr wert als jedes Gehalt – zumindest für mich.\n\n[Bridge]\nMut heißt nicht, keine Angst zu haben,\nMut heißt, trotz zitternder Knie loszugehen – mit offenen Fragen.\nUnd wenn du fällst, dann fällst du – aber nicht ins Leere:\nDu landest, oder du lernst – und beides ist eine Lehre.", "vocab": [["mit dem Rücken zur Wand stehen", "in einer sehr schwierigen Lage sein, keinen Ausweg sehen"], ["der Trott", "eintöniger, immer gleicher Ablauf"], ["auf dem Teppich bleiben", "realistisch und bescheiden bleiben"], ["mit dem Feuer spielen", "ein gefährliches Risiko eingehen"], ["jemandem nicht geheuer sein", "jemandem unheimlich oder verdächtig vorkommen"], ["ins kalte Wasser springen", "etwas Neues ohne Vorbereitung beginnen"], ["alles auf eine Karte setzen", "alles für eine einzige Möglichkeit riskieren"], ["kleine Brötchen backen", "bescheiden sein, mit wenig zufrieden sein"], ["in die Hose gehen (ugs.)", "misslingen, schiefgehen"], ["das Handtuch werfen", "aufgeben"], ["standhalten (hielt stand)", "nicht nachgeben, durchhalten"], ["in Scharen", "in großer Zahl"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Ich stand mit dem Rücken zur ___, der Job war weg, die Kasse leer,", "Alle sagten: „Bleib auf dem ___! Spiel nicht mit dem Feuer!", "Ich springe ins kalte ___, ich wage den ersten Schritt –", "ich setze alles auf eine ___ – und lasse die Angst draußen warten.", "so manches ging in die Hose – doch ich warf nie das ___, ich hielt stand."], "solutions": ["Wand", "Teppich", "Wasser", "Karte", "Handtuch"]}, "suno": "ec35d526-3c46-4345-b94b-817ebd93de34"}, {"id": "c1-05-man-sagt", "level": "C1", "title": "Man sagt", "theme": "Medien und Wahrheit: Politik, Influencer, Schlagzeilen, Desinformation, Vertrauen", "grammar": "Konjunktiv I in der indirekten Rede (er habe, sie seien, es gebe); Redewiedergabe mit distanzierenden Verben (behaupten, schwören, warnen)", "intro": "Wer sagt was – und wer hat es bezahlt? Dieser düstere Trip-Hop-Song über Medien und Wahrheit ist fast komplett in indirekter Rede geschrieben. Perfekt, um den Konjunktiv I zu üben.", "lyrics": "[Verse 1]\nEin Minister sagt, er habe von all dem nichts gewusst,\ndie Aufregung sei ein Sturm im Wasserglas – man sei sich der Verantwortung bewusst.\nEine Sprecherin erklärt, die Zahlen seien korrekt,\nnichts werde vertuscht und nichts werde versteckt.\n\n[Pre-Chorus]\nEin Influencer schwört, sein Pulver mache jung und schlank,\nmit dem Code in seiner Bio gebe es Rabatt – na, vielen Dank!\n\n[Chorus]\nMan sagt, man hört, man liest, man teilt,\ndie Wahrheit hinkt hinterher, während die Lüge eilt.\nWer sagt was, warum – und wer hat es bezahlt?\nBevor du es glaubst, frag dich, wer da die Bilder malt.\n\n[Verse 2]\nDie Schlagzeile schreit, und der Artikel flüstert,\nder Kontext geht verloren, irgendwo im Feed, der leise knistert.\nEin aus dem Zusammenhang gerissenes Zitat\ngeht viral, bevor ein Mensch es überprüft hat.\n\n[Chorus]\nMan sagt, man hört, man liest, man teilt,\ndie Wahrheit hinkt hinterher, während die Lüge eilt.\nWer sagt was, warum – und wer hat es bezahlt?\nBevor du es glaubst, frag dich, wer da die Bilder malt.\n\n[Verse 3]\nDie Redaktion teilt mit, man habe den Fehler korrigiert,\ndoch die Korrektur wird kaum gelesen, kaum geteilt, kaum registriert.\nEin Experte warnt, Vertrauen sei ein knappes Gut:\nWer es verspiele, gewinne es nur langsam zurück – mit Zeit, Geduld und Mut.\n\n[Bridge]\nIch sage nicht, alles sei gelogen,\nich sage nur: Die Wahrheit ist oft ein wenig verbogen.\nPrüf die Quelle, lies weiter, zweifle mit Verstand –\ndas Urteil liegt am Ende in deiner eigenen Hand.\n\n[Chorus]\nMan sagt, man hört, man liest, man teilt,\ndie Wahrheit hinkt hinterher, während die Lüge eilt.\nWer sagt was, warum – und wer hat es bezahlt?\nBevor du es glaubst, frag dich, wer da die Bilder malt.\n\n[Outro]\nMan sagt … aber was sagst du?", "vocab": [["ein Sturm im Wasserglas", "große Aufregung über eine unwichtige Sache"], ["vertuschen", "etwas Negatives absichtlich verbergen"], ["schwören", "feierlich versichern, dass etwas wahr ist"], ["die Schlagzeile, die Schlagzeilen", "groß gedruckte Überschrift eines Artikels"], ["etwas aus dem Zusammenhang reißen", "einen Teil ohne seinen Kontext zitieren, sodass sich der Sinn verändert"], ["viral gehen", "sich sehr schnell im Internet verbreiten"], ["die Redaktion, die Redaktionen", "Team, das die Inhalte einer Zeitung oder eines Senders verantwortet"], ["ein knappes Gut", "etwas Wertvolles, von dem es nur wenig gibt"], ["verspielen", "durch eigenes Verhalten verlieren"], ["die Quelle, die Quellen", "Ursprung einer Information"], ["hinterherhinken", "langsamer sein als andere, zurückbleiben"], ["das Urteil, die Urteile", "abschließende Bewertung, Entscheidung"]], "gap": {"type": "gap", "title": "Aufgabe 2: Lückentext", "instruction": "Hör das Lied und ergänze die fehlenden Wörter.", "items": ["Eine Sprecherin erklärt, die Zahlen ___ korrekt,", "die Wahrheit hinkt hinterher, während die ___ eilt.", "Ein aus dem Zusammenhang ___ Zitat", "Ein Experte warnt, Vertrauen sei ein ___ Gut:", "Prüf die ___, lies weiter, zweifle mit Verstand –"], "solutions": ["seien", "Lüge", "gerissenes", "knappes", "Quelle"]}, "suno": "18d78355-2a3f-444a-9499-f9d8f55f0feb"}];
